# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

normalize_phone = fun(raw) {
    # Extract digits only
    digits = regex.replace(raw, "[^0-9]", "")
    # If 11 digits starting with 1, use last 10; if 10 digits, use those
    ten = if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return text.slice(digits, 1)
    } else if text.length(digits) == 10 {
        return digits
    } else if text.length(digits) > 10 and text.starts_with(digits, "1") {
        return text.slice(digits, 1, 11)
    } else if text.length(digits) >= 10 {
        return text.slice(digits, text.length(digits) - 10)
    } else {
        return digits
    }
    return "+1" + ten
}

is_e164 = fun(phone) {
    return regex.test(phone, "^\\+1[0-9]{10}$")
}

results = for contact in contacts {
    needs_phone = contact.phone != null and not is_e164(contact.phone)
    new_phone = normalize_phone(contact.phone) if needs_phone else null

    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = text.lower(parts[1]) if list.length(parts) == 2 else ""
    needs_company = (contact.company == null or contact.company == "") and domain != "" and domain in domain_map
    new_company = domain_map[domain] if needs_company else null

    updated = false
    if needs_phone or needs_company {
        u = update_contact({
            id: contact.id,
            phone: new_phone if needs_phone else null,
            company: new_company if needs_company else null
        })
        updated = true
    }

    return {
        phone_fixed: needs_phone,
        company_filled: needs_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submit }

